def ci_of(d):
    if d is None:
        return None, None, None
    if "ci" in d:
        return d["est"], d["ci"][0], d["ci"][1]
    return d.get("est"), d.get("lo"), d.get("hi")


# ---------------------------------------------------------------- S2
def s2(F, F3, out):
    X = json.load(open(os.path.join(F3, "metrics_mixture_controls.json"))); H = 96; fig = fig_(H)
    sds = [0.0, 0.1, 0.2, 0.3]; rowsA = X["rows"]["a"]
    a1 = ax_(fig, H, 14, 6, 34, 32); a2 = ax_(fig, H, 60, 6, 34, 32); letter(fig, H, 1, 2, "a")
    for cx, col, lab in (("hESC", C["hESC"], "hESC"), ("K562_gw", C["K562"], "K562")):
        for n, ls, mfc in ((400, "-", None), (150, "--", "white")):
            S = [X["a_continuous"]["%s|n%d|sd%.1f|e0.0" % (cx, n, s)] for s in sds]
            for s, v in zip(sds, S):
                rr = [r for r in rowsA if r["ctx"] == cx and r["n"] == n and abs(r["sd"] - s) < 1e-9 and r["e_true"] == 0]
                assert len(rr) == v["n_genes"]
            a1.plot(sds, [v["frac_mixture"] for v in S], ls=ls, marker="o", ms=2.5, color=col, mfc=mfc or col, label="%s, %d cells" % (lab, n))
            em = np.array([v["e_hat_median"] for v in S]); q = np.array([v["e_hat_q"] for v in S])
            off = (0.006 if cx == "hESC" else -0.006) + (0.003 if n == 150 else 0)
            a2.errorbar(np.array(sds) + off, em, yerr=[em - q[:, 0], q[:, 1] - em], fmt="o", ls=ls, ms=2.5, color=col, lw=0.8,
                        elinewidth=0.5, capsize=1, mfc=mfc or col)
    for a in (a1, a2):
        a.set_xticks(sds); a.set_xlabel("SD of knockdown across cells")
    a1.set_ylabel("Fraction called two groups"); a1.set_ylim(-0.03, 1.05); title(a1, "Continuous knockdown, e = 0")
    a2.set_ylabel("Estimated e"); a2.set_ylim(-0.01, 0.4); title(a2, "Continuous knockdown, e = 0")
    fig.legend(*a1.get_legend_handles_labels(), loc="upper left", bbox_to_anchor=(14 / W, 1 - 47 / H), ncol=4, handlelength=1.6, columnspacing=1.0)
    # b: non-target genes
    ax = ax_(fig, H, 106, 6, 32, 32); letter(fig, H, 96, 2, "b")
    Bt = X["b_nontarget_hesc"]; w = 0.36
    for i, t in enumerate(TK):
        ax.bar(i - w / 2, Bt[t]["own_frac_mixture"], w, color=C["hESC"], lw=0, label="Own gene" if i == 0 else None)
        ax.bar(i + w / 2, Bt[t]["nontarget_frac_mixture"], w, color=BLACK, lw=0, label="Other genes, same cells" if i == 0 else None)
    tier_ticks(ax); ax.set_ylim(0, 1.25); ax.set_yticks([0, 0.5, 1]); ax.set_ylabel("Fraction called two groups"); ax.set_xlabel("DepMap gene effect")
    ax.legend(loc="upper left", ncol=1, handlelength=1.0, bbox_to_anchor=(0, 1.08)); title(ax, "")
    # c: free second component
    ax = ax_(fig, H, 150, 6, 30, 32); letter(fig, H, 140, 2, "c")
    Cf = X["c_free_level"]
    for off, cx, col in ((-0.18, "hESC", C["hESC"]), (0.18, "K562_gw", C["K562"])):
        for i, t in enumerate(TK):
            v = np.array([r["r_esc"] for r in X["rows"]["c"] if r["ctx"] == cx and r["essentiality"] is not None
                          and np.isfinite(r["essentiality"]) and {"lt_-1": (-9, -1), "-1_-0.5": (-1, -0.5), "-0.5_-0.2": (-0.5, -0.2), "gt_-0.2": (-0.2, 9)}[t][0] <= r["essentiality"] < {"lt_-1": (-9, -1), "-1_-0.5": (-1, -0.5), "-0.5_-0.2": (-0.5, -0.2), "gt_-0.2": (-0.2, 9)}[t][1]
                          and r["r_esc"] is not None], float)
            assert abs(np.median(v) - Cf[cx][t]["r_esc_median"]) < 1e-9
            bp = ax.boxplot([v], positions=[i + off], widths=0.3, showfliers=False, patch_artist=True, medianprops=dict(color=BLACK, lw=0.8),
                            whiskerprops=dict(lw=0.5, color=col), capprops=dict(lw=0.5, color=col), boxprops=dict(lw=0.5, color=col))
            bp["boxes"][0].set_facecolor(col); bp["boxes"][0].set_alpha(0.45)
    ax.axhline(1, color=LGREY, lw=0.6, zorder=0)
    tier_ticks(ax); ax.set_ylim(0.3, 1.45); ax.set_xlabel("DepMap gene effect"); ax.set_ylabel("Level of the escaping group\n/ control level")
    ax.legend(handles=[Patch(color=C["hESC"], alpha=0.45, label="hESC"), Patch(color=C["K562"], alpha=0.45, label="K562")], loc="upper left", ncol=2, handlelength=1.0)
    # d: the test prefers two groups for real perturbations, not for thinned controls (old Fig. 2c)
