# ---------------------------------------------------------------- S3
def s3(A, B, out):
    H = 114; fig = fig_(H)
    D = B["drepanos"]["days"]; days = [4, 7, 10, 14]
    sel = [("NAMPT", "CRISPRi", BLACK, "-", "o"), ("OGFOD1", "CRISPRi", BLACK, "-", "s"), ("RPL9", "CRISPRko", BLACK, "--", "^"),
           ("CTBP1", "CRISPRi", GREY, "-", "D")]
    for j, (key, ylab, logy) in enumerate((("abundance_vs_nonessential", "Relative abundance", False), ("residual_ref", "Remaining target expression", False),
                                           ("response_ref", "Response size\n((log2 FC)²)", True))):
        ax = ax_(fig, H, 14 + j * 58, 6, 44, 32)
        for gene, arm, col, ls, mk in sel:
            xs, y = [], []
            for d in days:
                t = D[str(d)].get(arm, {}).get("targets", {}).get(gene)
                if t and t.get(key) is not None and (not logy or t[key] > 0):
                    xs.append(d); y.append(t[key])
            ax.plot(xs, y, marker=mk, ms=2.8, color=col, ls=ls, label="%s (%s)" % (gene, "CRISPRi" if arm == "CRISPRi" else "knockout"))
        ax.set_xticks(days); ax.set_xlabel("Time after transduction (days)"); ax.set_ylabel(ylab)
        if logy:
            ax.set_yscale("log")
    letter(fig, H, 1, 2, "a")
    fig.legend(*ax.get_legend_handles_labels(), loc="upper left", bbox_to_anchor=(14 / W, 1 - 46 / H), ncol=4, handlelength=1.8, columnspacing=1.2)
    # b: datasets by harvest day
    ax = ax_(fig, H, 14, 62, 100, 34); letter(fig, H, 1, 58, "b")
    ladder = [(3, 13.5, "iPSC", C["other"], "random", (5, 0), "left"), (6, 23.4, "16 lines (KO)", C["other"], "constructs", (5, 0), "left"),
              (6, 11.1, "K562", C["K562"], "random", (-5, 0), "right"), (7, 7.5, "RPE1", C["RPE1"], "random", (5, -4), "left"),
              (7, 3.8, "Jurkat", C["Jurkat"], "random", (5, 0), "left"), (7, 8.6, "HepG2", C["HepG2"], "random", (5, 5), "left"),
              (8, 1.38, "hESC", C["hESC"], "guides", (5, 0), "left"), (11, 19.6, "CD4+ T rest", C["CD4"], "guides", (5, 0), "left"),
              (13, 11.4, "CD4+ T stim", C["CD4"], "guides", (5, 0), "left")]
    for d, r, lab, col, unit, off, ha in ladder:
        mk = "o" if unit == "random" else ("s" if unit == "guides" else "^")
        ax.scatter([d], [r], s=14, color=col, marker=mk, zorder=3, lw=0)
        ax.annotate(lab, (d, r), textcoords="offset points", xytext=off, fontsize=6, ha=ha, va="center")
    ax.axhline(1, color=LGREY, lw=0.6, zorder=0)
    ax.set_yscale("log"); ax.set_ylim(0.8, 60); ax.set_xlim(1.5, 16); ax.set_yticks([1, 3, 10, 30]); ax.set_yticklabels(["1", "3", "10", "30"]); ax.minorticks_off()
    ax.set_xlabel("Harvest (days after transduction)"); ax.set_ylabel("Response ratio, most\nessential / non-essential")
    ax.legend(handles=[Line2D([], [], marker=m, ls="none", color=GREY, ms=3.5, label=l) for m, l in (("o", "Random halves"), ("s", "Guide halves"), ("^", "Independent constructs"))],
              loc="lower right", handletextpad=0.2, labelspacing=0.3)
    # c: 16 lines by depletion bin
    ax = ax_(fig, H, 134, 62, 46, 34); letter(fig, H, 124, 58, "c")
    bins = B["maffa"]["response_by_depletion_bin"]; ks = list(bins.keys())
    ax.bar(range(len(ks)), [bins[k]["response_median"] for k in ks], 0.62, color=GREY)
    ax.set_xticks(range(len(ks))); ax.set_xticklabels([("≥ " + k.strip("()[]").split(",")[0]) if "inf" in k else k.replace(", ", "–").strip("()[]") for k in ks], rotation=40, ha="right")
    ax.set_yscale("log"); ax.set_xlabel("Relative cells remaining"); ax.set_ylabel("Response size\n((log2 FC)²)"); title(ax, "16 cancer lines, day 6")
    save(fig, out, "figS3_time_course")


# ---------------------------------------------------------------- S6
def s6(F3, out):
    Nd = json.load(open(os.path.join(F3, "metrics_nadig_pairs.json"))); O = json.load(open(os.path.join(F3, "metrics_orion_matched2.json")))
    H = 62; fig = fig_(H)
    ax = ax_(fig, H, 24, 8, 76, 44); letter(fig, H, 1, 4, "a")
    pairs = sorted(Nd["pairs"], key=lambda p: Nd["pairs"][p]["sets"]["all"]["lt_-1"]["total_vs_within"]["rho_a"]["median"])
    for i, p in enumerate(pairs):
        d = Nd["pairs"][p]["sets"]["all"]["lt_-1"]["total_vs_within"]
        a_, b_ = d["rho_a"]["median"], d["rho_b"]["median"]
        ax.plot([a_, b_], [i, i], color=LGREY, lw=0.8, zorder=1)
        for v, key, fc in ((a_, "rho_a", "white"), (b_, "rho_b", BLACK)):
            lo, hi = d[key]["ci95"]; ax.plot([lo, hi], [i, i], color=BLACK, lw=0.5, zorder=2)
            ax.scatter([v], [i], s=14, facecolor=fc, edgecolor=BLACK, lw=0.7, zorder=3)
    ax.set_yticks(range(len(pairs))); ax.set_yticklabels(pairs); ax.set_xlim(0.38, 0.82); ax.set_ylim(-0.6, len(pairs) - 0.4)
    ax.set_xlabel("Direction agreement ρ"); title(ax, "Four cancer lines, most essential")
    ax.legend(handles=[Line2D([], [], marker="o", ls="none", mfc="white", mec=BLACK, ms=3.5, label="Total response"),
                       Line2D([], [], marker="o", ls="none", mfc=BLACK, mec=BLACK, ms=3.5, label="Composition removed")],
              loc="lower right", handletextpad=0.2)
    ax = ax_(fig, H, 124, 8, 56, 40); letter(fig, H, 112, 4, "b")
    T = O["tiers"]["lt_-1"]
    bins = [("dR<-0.1", "< −0.1"), ("|dR|<=0.1", "−0.1 to 0.1"), ("0.1<dR<=0.3", "0.1 to 0.3"), ("dR>0.3", "> 0.3")]
    pts = [("All", T["all"], "white")] + [(lab, T["bins"][k], BLACK) for k, lab in bins]
    for i, (lab, d, fc) in enumerate(pts):
        lo, hi = d["ci95"]; ax.plot([i, i], [lo, hi], color=BLACK, lw=0.6)
        ax.scatter([i], [d["ratio"]], s=14, facecolor=fc, edgecolor=BLACK, lw=0.7, zorder=3)
    assert abs(T["bins"]["|dR|<=0.1"]["ratio"] - 0.87) < 0.005
    ax.axhline(1, color=LGREY, lw=0.6, zorder=0); ax.axvline(0.5, color=LGREY, lw=0.5)
    ax.set_yscale("log"); ax.set_ylim(0.3, 5); ax.set_yticks([0.5, 1, 2, 4]); ax.set_yticklabels(["0.5", "1", "2", "4"]); ax.minorticks_off()
    ax.set_xticks(range(len(pts))); ax.set_xticklabels([p[0] for p in pts])
    ax.set_xlabel("Remaining expression, HEK293T − HCT116"); ax.set_ylabel("HEK293T / HCT116 response size"); title(ax, "X-Atlas/Orion, most essential")
    save(fig, out, "figS6_published_comparisons")


# ---------------------------------------------------------------- S8
def s8(F, A, B, N, out):
    H = 134; fig = fig_(H)
    # a: counterfactual schematic
    ax = ax_(fig, H, 4, 4, 50, 40); ax.set_xlim(0, 10); ax.set_ylim(0, 10); ax.axis("off"); letter(fig, H, 1, 2, "a")
    for i, (x0, lab, frac) in enumerate(((0.4, "Control", [0.33, 0.33, 0.34]), (5.4, "Perturbed", [0.62, 0.2, 0.18]))):
        xx = x0
        for f, c in zip(frac, ("#e6e6e6", "#a6a6a6", "#595959")):
            ax.add_patch(Rectangle((xx, 8.0), 4.2 * f, 1.0, fc=c, ec="white", lw=0.5)); xx += 4.2 * f
        ax.text(x0 + 2.1, 7.3, lab, ha="center", fontsize=6)
    ax.text(0.4, 6.2, "Composition term: stage mixture of the\nperturbed cells, within-stage expression\nof controls", fontsize=6, va="top")
    ax.text(0.4, 3.2, "Within-cell term: the remainder", fontsize=6, va="top")
    ax.text(0.4, 1.8, "Selection term: recomputed from\nknocked-down cells only", fontsize=6, va="top")
    ax.legend(handles=[Patch(color=c, label=l) for c, l in (("#e6e6e6", "G1"), ("#a6a6a6", "S"), ("#595959", "G2/M"))], loc="upper center",
              bbox_to_anchor=(0.5, 1.05), ncol=3, handlelength=1.0)
    # b: composition share (lower bound) and selection term
    ci = A["ci"]; c5 = B["ci_5090"]["bm"]
    ctx = [("RPE1", ci["bm"]["RPE1"]), ("HepG2", c5["HepG2"]), ("Jurkat", c5["Jurkat"]), ("K562", ci["bm"]["K562"]), ("hESC", ci["bm"]["hESC"])]
    ax = ax_(fig, H, 68, 6, 46, 36); letter(fig, H, 58, 2, "b")
    for i, (nm, d) in enumerate(ctx):
        e, lo, hi = ci_of(d["lt_-1"]["comp_share"])
        ax.errorbar([i], [e], yerr=[[max(e - lo, 0)], [max(hi - e, 0)]], fmt="o", ms=3, color=C[nm], elinewidth=0.6, capsize=1.2)
    e, lo, hi = ci_of(ci["bv"]["lt_-1"]["comp_share"])
    ax.errorbar([3.3], [e], yerr=[[e - lo], [hi - e]], fmt="s", ms=3, mfc="white", color=C["K562"], elinewidth=0.6, capsize=1.2)
    ax.set_xticks(range(5)); ax.set_xticklabels([c[0] for c in ctx]); ax.set_xlim(-0.6, 4.6)
    ax.set_yscale("log"); ax.set_ylim(0.002, 0.5); ax.set_ylabel("Composition share, lower bound")
    ax.set_yticks([0.003, 0.01, 0.03, 0.1, 0.3]); ax.set_yticklabels(["0.003", "0.01", "0.03", "0.1", "0.3"]); ax.minorticks_off()
    ax.legend(handles=[Line2D([], [], marker="o", ls="none", color=GREY, ms=3, label="Random halves"),
                       Line2D([], [], marker="s", ls="none", mfc="white", mec=GREY, ms=3, label="K562, two screens")], loc="upper right", handletextpad=0.2)
    ax = ax_(fig, H, 132, 6, 48, 36); letter(fig, H, 122, 2, "c")
    order = sorted(ctx, key=lambda c: -c[1]["lt_-1"]["selection"]["est"])
    for i, (nm, d) in enumerate(order):
        e, lo, hi = ci_of(d["lt_-1"]["selection"])
        ax.errorbar([i], [e], yerr=[[e - lo], [hi - e]], fmt="o", ms=3, color=C[nm], elinewidth=0.6, capsize=1.2)
    ax.axhline(1, color=LGREY, lw=0.6, zorder=0)
    ax.set_xticks(range(5)); ax.set_xticklabels([c[0] for c in order]); ax.set_xlim(-0.6, 4.6); ax.set_ylabel("Selection term")
    # d: cycle genes removed
    ax = ax_(fig, H, 14, 58, 46, 30); letter(fig, H, 1, 54, "d")
    src = {"RPE1": A["fig3"]["RPE1"], "K562": A["fig3"]["K562"], "hESC": A["fig3"]["hESC"], "HepG2": B["budget"]["HepG2"], "Jurkat": B["budget"]["Jurkat"]}
    names = ["RPE1", "HepG2", "Jurkat", "K562", "hESC"]; w = 0.36; x = np.arange(len(names))
    ax.bar(x - w / 2, [src[n]["random"]["lt_-1"]["comp_share"] for n in names], w, color=GREY, label="All response genes")
    ax.bar(x + w / 2, [src[n]["random_no_cycle_genes"]["lt_-1"]["comp_share"] for n in names], w, color=BLACK, label="Cycle genes removed")
    ax.set_xticks(x); ax.set_xticklabels(names); ax.set_yscale("log"); ax.set_ylim(0.002, 0.6); ax.set_ylabel("Composition share")
    ax.set_yticks([0.003, 0.01, 0.03, 0.1, 0.3]); ax.set_yticklabels(["0.003", "0.01", "0.03", "0.1", "0.3"]); ax.minorticks_off()
    ax.legend(loc="upper right", handlelength=1.0)
    # e: null-perturbation control
    ax = ax_(fig, H, 76, 58, 50, 30); letter(fig, H, 66, 54, "e")
    rows = [("hESC", A["fig3"]["hESC|budget_hesc_nc"]["negative_control"]), ("CD4 d2", A["fig3"]["CD4_D2rest|nc"]["negative_control"]),
            ("CD4 d3", A["fig3"]["CD4_D3rest|d34"]["negative_control"]), ("CD4 d4", A["fig3"]["CD4_D4rest|d34"]["negative_control"])]
    x = np.arange(len(rows)); w = 0.36
    ax.bar(x - w / 2, [r[1]["ratio"] for r in rows], w, color="white", edgecolor=BLACK, lw=0.5, label="Random halves")
    ax.bar(x + w / 2, [r[1]["guide_ratio"] for r in rows], w, color=BLACK, label="Guide halves")
    ax.axhline(0.10, color=BLACK, lw=0.5, ls="--", label="Limit (0.10)")
    ax.set_xticks(x); ax.set_xticklabels([r[0] for r in rows]); ax.set_ylabel("Null perturbations /\nnon-essential stratum")
    ax.legend(loc="upper left", bbox_to_anchor=(1.02, 1.0), handlelength=1.2, labelspacing=0.3)
    # f: removing the composition term raises agreement with K562 (old Fig. 5c)
    ax = ax_(fig, H, 14, 98, 60, 16 + 14); letter(fig, H, 1, 94, "f")
    sets = [("RPE1", "lt_-1"), ("RPE1", "-1_-0.5"), ("HepG2", "lt_-1"), ("HepG2", "-1_-0.5")]
    kinds = [("delta_own", BLACK, "Own composition"), ("delta_same_tier_mismatch", GREY, "Another gene, same stratum"),
             ("delta_nonessential_mismatch", LGREY, "Another gene, non-essential")]
    w = 0.25
    for i_, (cx, t) in enumerate(sets):
        for j_, (key, col, lab) in enumerate(kinds):
            ax.bar(i_ + (j_ - 1) * w, N[cx][t][key], width=w * 0.92, color=col, lw=0, label=lab if i_ == 0 else None)
    ax.set_xticks(range(4)); ax.set_xticklabels(["RPE1\n< −1", "RPE1\n−1 to −0.5", "HepG2\n< −1", "HepG2\n−1 to −0.5"])
    ax.set_ylim(0, 0.11); ax.set_xlim(-0.5, 3.5); ax.set_ylabel("Change in agreement of\ndirection with K562")
    ax.legend(loc="upper left", bbox_to_anchor=(1.02, 1.0), handlelength=1.0, labelspacing=0.25)
    save(fig, out, "figS8_composition")


# ---------------------------------------------------------------- S9
def s9(A, B, out):
    H = 96; fig = fig_(H)
    ax = ax_(fig, H, 14, 6, 50, 34); letter(fig, H, 1, 2, "a")
    labs, obs, err, cols = [], [], [], []
    for lab in ("hESC", "K562", "RPE1"):
        for t, tl in zip(TK[:2], ("< −1", "−1 to −0.5")):
            y = A["fig6a"][lab]["Y0"][t]
            if "sd_observed" in y:
                labs.append("%s\n%s" % (lab, tl)); obs.append(y["sd_observed"]); err.append(y["sd_error"]); cols.append(C[lab])
